// One timbre, one polyphonic voice engine, one shared stereo effects chain.
const MAMB_SYNTH_KEYS=['thickness','velocitySensitivity','analogCharacter','cross','lfo','vib','drift','pw','pwm','level1','level2','ring','noise','drive','cutoff','res','envAmt','motion','master','aa','ad','as','ar','fa','fd','fs','fr','detune','semi2','keyTrack','lfo1Depth','lfo2Rate','lfo2Depth','sync','wave1','wave2','oct2','filter','bend','lfo1Wave','lfo2Wave','voiceMode'];
function createMambInstrument(initial,sr=48000,seed=12345){
 function synthValues(value){const result={};for(const key of MAMB_SYNTH_KEYS)if(key in value)result[key]=value[key];result.master=100;return result}
 // Shared fixed all-pass decorrelation: no extra timbre/voice or periodic chorus modulation.
 const thickL=new Float64Array(Math.max(1,Math.round(sr*.00073))),thickR=new Float64Array(Math.max(1,Math.round(sr*.00113)));let thickIndexL=0,thickIndexR=0,thickness=0,thicknessTarget=Number.isFinite(initial.thickness)?Math.max(0,Math.min(1,initial.thickness/100)):0;const thickAlpha=1-Math.exp(-1/(sr*.02));
 function spread(left,right){if(thicknessTarget===0&&thickness===0){right.set(left);return}for(let i=0;i<left.length;i++){thickness+=(thicknessTarget-thickness)*thickAlpha;if(Math.abs(thicknessTarget-thickness)<1e-8)thickness=thicknessTarget;const x=left[i],a=thickL[thickIndexL]-.45*x,b=thickR[thickIndexR]-.45*x;const nextL=x+.45*a,nextR=x+.45*b;thickL[thickIndexL]=Math.abs(nextL)<1e-24?0:nextL;thickR[thickIndexR]=Math.abs(nextR)<1e-24?0:nextR;if(++thickIndexL===thickL.length)thickIndexL=0;if(++thickIndexR===thickR.length)thickIndexR=0;const side=(a-b)*.30*thickness,gain=1/Math.sqrt(1+.18*thickness*thickness);left[i]=(x+side)*gain;right[i]=(x-side)*gain}}
 let inputGain=0,inputTarget=0;const inputAlpha=1-Math.exp(-1/(sr*.02));
 const synth=createMambEngine(synthValues(initial),sr,seed),effects=createMambEffects(initial,sr);
 function message(event){if(event.type==='audioInputGain'){if(Number.isFinite(event.value))inputTarget=Math.max(0,Math.min(1,event.value));return}if(event.type==='params'){if(Number.isFinite(event.value?.thickness))thicknessTarget=Math.max(0,Math.min(1,event.value.thickness/100));synth.message({type:'params',value:synthValues(event.value||{})});effects.setParameters(event.value||{})}else {synth.message(event);if(event.type==='panic'){inputTarget=0;thickL.fill(0);thickR.fill(0);effects.panic()}}}
 function render(left,right,inputL,inputR){synth.render(left);spread(left,right);if(inputL&&(inputTarget>0||inputGain>1e-8)){for(let i=0;i<left.length;i++){inputGain+=(inputTarget-inputGain)*inputAlpha;right[i]=right[i]+(inputR||inputL)[i]*inputGain;left[i]=left[i]+inputL[i]*inputGain}effects.process(left,right,left,right)}else effects.process(left,right,left,right)}
 function snapshot(){const state=synth.snapshot();state.effects=effects.snapshot();state.thicknessStereo={amount:thickness,target:thicknessTarget,allocatedBytes:thickL.byteLength+thickR.byteLength};return state}
 return {render,message,snapshot};
}
